+    ByteBuffer bb1 = ByteBuffer.wrap(test);
+    UnsynchronizedBuffer.Reader ub = new UnsynchronizedBuffer.Reader(bb1);
+    byte[] buf = new byte[10];
+    ub.readBytes(buf);
